// #Sireum

package factory_flow.Factory_Flow

import org.sireum._
import art._
import factory_flow._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait WorkRequestQualifier_Api {
  def id: Art.BridgeId
  def presentedWork_Id : Art.PortId
  def admissionToMaterial_Id : Art.PortId
  def admissionToPriority_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var admissionToMaterial: Factory_Flow.AdmissionFact = $

  def put_admissionToMaterial(value : Factory_Flow.AdmissionFact) : Unit = {
    Contract(
      Modifies(admissionToMaterial),
      Ensures(
        admissionToMaterial == value
      )
    )
    Spec {
      admissionToMaterial = value
    }

    Art.putValue(admissionToMaterial_Id, Factory_Flow.AdmissionFact_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var admissionToPriority: Factory_Flow.AdmissionFact = $

  def put_admissionToPriority(value : Factory_Flow.AdmissionFact) : Unit = {
    Contract(
      Modifies(admissionToPriority),
      Ensures(
        admissionToPriority == value
      )
    )
    Spec {
      admissionToPriority = value
    }

    Art.putValue(admissionToPriority_Id, Factory_Flow.AdmissionFact_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class WorkRequestQualifier_Initialization_Api (
  val id: Art.BridgeId,
  val presentedWork_Id : Art.PortId,
  val admissionToMaterial_Id : Art.PortId,
  val admissionToPriority_Id : Art.PortId) extends WorkRequestQualifier_Api

@datatype class WorkRequestQualifier_Operational_Api (
  val id: Art.BridgeId,
  val presentedWork_Id : Art.PortId,
  val admissionToMaterial_Id : Art.PortId,
  val admissionToPriority_Id : Art.PortId) extends WorkRequestQualifier_Api {

  // Logika spec var representing port state for incoming data port
  @spec var presentedWork: Factory_Flow.PresentedWorkRequest = $

  def get_presentedWork() : Option[Factory_Flow.PresentedWorkRequest] = {
    Contract(
      Ensures(
        Res == Some(presentedWork)
      )
    )
    val value : Option[Factory_Flow.PresentedWorkRequest] = Art.getValue(presentedWork_Id) match {
      case Some(Factory_Flow.PresentedWorkRequest_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port presentedWork.  Expecting 'Factory_Flow.PresentedWorkRequest_Payload' but received ${v}")
        None[Factory_Flow.PresentedWorkRequest]()
      case _ => None[Factory_Flow.PresentedWorkRequest]()
    }
    return value
  }
}
